package jals.build;

/**
 * Where a script's generated files go.
 *
 * <p>A write buffers bytes below the build's dedicated output root — {@code
 * target/jals/build/script/out} — and nothing is published unless the script finishes without a
 * {@link Build#error}: generated bytes are like the rest of the script's directives, held until a
 * successful evaluation is committed in one transaction. The value a write returns is the
 * canonical key of the file, which is what {@link Build#addSource} and
 * {@link Build#addClasspath} add to the later compile.
 *
 * <p>Paths are relative to that root and cannot escape it; an empty path names the root itself and
 * is refused, because committing the root as a regular file would make every later write fail
 * against its own ancestor.
 */
public final class Output {

    /**
     * Buffer {@code bytes} at the output-root-relative {@code path}, and return the file's key.
     *
     * <p>The key is what a later {@code build.addSource(key)} or {@code build.addClasspath(key)}
     * takes; it is project-relative, so it can be read back through {@link Project} in the same
     * run only after publication — but registering it with {@code Build} works immediately.
     */
    public static String write(String path, byte[] bytes) {
        char[] name = Text.of(path);
        int length = writeSize(name, bytes);
        return take(length);
    }

    /** Buffer the UTF-8 bytes of {@code text} at {@code path}, and return the file's key. */
    public static String writeText(String path, String text) {
        char[] name = Text.of(path);
        char[] chars = Text.of(text);
        int length = writeTextSize(name, chars);
        return take(length);
    }

    /** The key the last write left in the host's scratch slot, as a string. */
    private static String take(int length) {
        char[] chars = new char[length];
        takeKey(chars);
        return new String(chars);
    }

    private static native int writeSize(char[] path, byte[] bytes);

    private static native int writeTextSize(char[] path, char[] text);

    private static native void takeKey(char[] out);
}
